/// Structured explanation for one quiz question.
///
/// Produced by [QuizExplanationService] after the student answers.
/// Stored optionally in [RecordQuestion.explanation] for history replay
/// and PDF export (decision 0031).
library;

// ---------------------------------------------------------------------------
// Enums
// ---------------------------------------------------------------------------

enum GroundingStatus {
  /// Explanation sourced from the reviewed question bank.
  bankGrounded,

  /// Explanation generated by the AI; not formally reviewed.
  gemmaUngrounded,

  /// Service was unavailable or the question type is unsupported.
  unavailable,
}

// ---------------------------------------------------------------------------
// Table-row helpers
// ---------------------------------------------------------------------------

/// One row in the waste-bin comparison table shown in MCQ explanations.
class ComparisonRow {
  const ComparisonRow({
    required this.bin,
    required this.material,
    required this.accepted,
    this.isCorrect = false,
  });

  /// Bin / category name (e.g. "Sampah Organik").
  final String bin;

  /// Example material for this bin.
  final String material;

  /// Accepted items description.
  final String accepted;

  /// Whether this row is the correct bin for the scanned item (highlighted).
  final bool isCorrect;

  Map<String, dynamic> toJson() => {
    'bin': bin,
    'material': material,
    'accepted': accepted,
    'isCorrect': isCorrect,
  };

  factory ComparisonRow.fromJson(Map<String, dynamic> json) => ComparisonRow(
    bin: json['bin'] as String? ?? '',
    material: json['material'] as String? ?? '',
    accepted: json['accepted'] as String? ?? '',
    isCorrect: json['isCorrect'] as bool? ?? false,
  );
}

/// One rubric criterion row for essay scoring.
class RubricRow {
  const RubricRow({
    required this.criterion,
    required this.maxScore,
    required this.awardedScore,
    this.comment = '',
  });

  final String criterion;
  final int maxScore;
  final int awardedScore;
  final String comment;

  Map<String, dynamic> toJson() => {
    'criterion': criterion,
    'maxScore': maxScore,
    'awardedScore': awardedScore,
    'comment': comment,
  };

  factory RubricRow.fromJson(Map<String, dynamic> json) => RubricRow(
    criterion: json['criterion'] as String? ?? '',
    maxScore: (json['maxScore'] as num?)?.toInt() ?? 0,
    awardedScore: (json['awardedScore'] as num?)?.toInt() ?? 0,
    comment: json['comment'] as String? ?? '',
  );
}

// ---------------------------------------------------------------------------
// Main model
// ---------------------------------------------------------------------------

/// Full structured explanation for one quiz question.
class QuizExplanation {
  const QuizExplanation({
    required this.summary,
    required this.correctAnswerReason,
    this.selectedAnswerFeedback = '',
    this.conceptExplanation = '',
    this.comparisonRows = const [],
    this.learningTakeaway = '',
    this.keyIdea = '',
    this.steps = const [],
    this.source = '',
    this.generatedAt,
    this.model,
    this.sourceTitle,
    this.sourceSection,
    this.sourcePage,
    this.quote,
    this.bankId,
    this.groundingStatus = GroundingStatus.unavailable,
    // Essay-specific
    this.essayScore,
    this.essayFeedback,
    this.rubricRows,
    this.referenceAnswer,
    this.lang,
    this.alt,
  });

  /// Language the text was written in ('en'/'id'); null = the record's language (decision 0185).
  final String? lang;

  /// The same explanation in the other app language, made in the same AI reply.
  final QuizExplanation? alt;

  /// Short paragraph summarising what was asked and what was correct.
  final String summary;

  /// Why the correct answer is correct.
  final String correctAnswerReason;

  /// Why the student's (wrong) answer was incorrect; empty if correct.
  final String selectedAnswerFeedback;

  /// Broader concept explanation placed in the PDF body.
  final String conceptExplanation;

  /// Rows for the waste-bin comparison table; may be empty.
  final List<ComparisonRow> comparisonRows;

  /// Take-away sentence shown in italic at the bottom of the explanation card.
  final String learningTakeaway;

  final String keyIdea;
  final List<String> steps;
  final String source;
  final DateTime? generatedAt;
  final String? model;

  bool get isComplete =>
      !isUnavailable &&
      keyIdea.isNotEmpty &&
      (source == 'ai' || source == 'aiWithBank' || source == 'bank');

  // Source attribution
  final String? sourceTitle;
  final String? sourceSection;
  final String? sourcePage;

  /// The module passage (bank questions only) and the bank item id (decision 0175).
  final String? quote;
  final String? bankId;
  final GroundingStatus groundingStatus;

  // Essay-specific fields
  final int? essayScore;
  final String? essayFeedback;
  final List<RubricRow>? rubricRows;
  final String? referenceAnswer;

  bool get isUnavailable => groundingStatus == GroundingStatus.unavailable;

  Map<String, dynamic> toJson() => {
    'summary': summary,
    'keyIdea': keyIdea,
    'steps': steps,
    'source': source,
    if (generatedAt != null) 'generatedAt': generatedAt!.toIso8601String(),
    if (model != null) 'model': model,
    'correctAnswerReason': correctAnswerReason,
    if (selectedAnswerFeedback.isNotEmpty)
      'selectedAnswerFeedback': selectedAnswerFeedback,
    if (conceptExplanation.isNotEmpty) 'conceptExplanation': conceptExplanation,
    if (comparisonRows.isNotEmpty)
      'comparisonRows': comparisonRows.map((r) => r.toJson()).toList(),
    if (learningTakeaway.isNotEmpty) 'learningTakeaway': learningTakeaway,
    if (sourceTitle != null) 'sourceTitle': sourceTitle,
    if (sourceSection != null) 'sourceSection': sourceSection,
    if (sourcePage != null) 'sourcePage': sourcePage,
    if (quote != null) 'quote': quote,
    if (bankId != null) 'bankId': bankId,
    'groundingStatus': groundingStatus.name,
    if (essayScore != null) 'essayScore': essayScore,
    if (essayFeedback != null) 'essayFeedback': essayFeedback,
    if (rubricRows != null)
      'rubricRows': rubricRows!.map((r) => r.toJson()).toList(),
    if (referenceAnswer != null) 'referenceAnswer': referenceAnswer,
    if (lang != null) 'lang': lang,
    if (alt != null) 'alt': alt!.toJson(),
  };

  factory QuizExplanation.fromJson(Map<String, dynamic> json) {
    final groundingRaw = json['groundingStatus'] as String?;
    final grounding = GroundingStatus.values.firstWhere(
      (s) => s.name == groundingRaw,
      orElse: () => GroundingStatus.unavailable,
    );
    return QuizExplanation(
      summary: json['summary'] as String? ?? '',
      keyIdea: json['keyIdea'] as String? ?? '',
      steps: (json['steps'] as List?)?.cast<String>() ?? const [],
      source: json['source'] as String? ?? '',
      generatedAt: DateTime.tryParse(json['generatedAt'] as String? ?? ''),
      model: json['model'] as String?,
      correctAnswerReason: json['correctAnswerReason'] as String? ?? '',
      selectedAnswerFeedback: json['selectedAnswerFeedback'] as String? ?? '',
      conceptExplanation: json['conceptExplanation'] as String? ?? '',
      comparisonRows:
          (json['comparisonRows'] as List<dynamic>?)
              ?.map((r) => ComparisonRow.fromJson(r as Map<String, dynamic>))
              .toList() ??
          const [],
      learningTakeaway: json['learningTakeaway'] as String? ?? '',
      sourceTitle: json['sourceTitle'] as String?,
      sourceSection: json['sourceSection'] as String?,
      sourcePage: json['sourcePage'] as String?,
      quote: json['quote'] as String?,
      bankId: json['bankId'] as String?,
      groundingStatus: grounding,
      essayScore: (json['essayScore'] as num?)?.toInt(),
      essayFeedback: json['essayFeedback'] as String?,
      rubricRows: (json['rubricRows'] as List<dynamic>?)
          ?.map((r) => RubricRow.fromJson(r as Map<String, dynamic>))
          .toList(),
      referenceAnswer: json['referenceAnswer'] as String?,
      lang: json['lang'] as String?,
      alt: json['alt'] is Map
          ? QuizExplanation.fromJson(
              Map<String, dynamic>.from(json['alt'] as Map),
            )
          : null,
    );
  }

  /// A placeholder shown when the service is unavailable.
  static const unavailable = QuizExplanation(
    summary: 'Penjelasan belum tersedia untuk soal ini.',
    correctAnswerReason: '',
    groundingStatus: GroundingStatus.unavailable,
  );
}
